package in.ac.rtu.medicare.rmi; import in.ac.rtu.medicare.service.AppointmentService; import java.rmi.*; import java.rmi.server.*; import java.time.*; import java.util.*;
public class RemoteAppointmentServiceImpl extends UnicastRemoteObject implements RemoteAppointmentService {private final AppointmentService service=new AppointmentService();public RemoteAppointmentServiceImpl()throws RemoteException{}public String book(long p,long d,LocalDateTime at,String reason)throws RemoteException{try{return "Booked appointment #"+service.book(p,d,at.toString(),reason);}catch(Exception e){throw new RemoteException("Booking failed: "+e.getMessage(),e);}}public List<String> availability(long d,LocalDate date){return List.of("Availability requires doctor_availability lookup; use web module for live slots.");}}
